import{_ as i,l,o as e,c as s,v as r,p as n,x as t,d,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"动态链接直觉","description":"","frontmatter":{"title":"动态链接直觉","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dynamic-link-preview.md","filePath":"cs/dynamic-link-preview.md","lastUpdated":1789023840000}'),p={name:"cs/dynamic-link-preview.md"};function A(B,a,h,m,_,u){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="动态链接直觉" tabindex="-1">动态链接直觉 <a class="header-anchor" href="#动态链接直觉" aria-label="Permalink to &quot;动态链接直觉&quot;">​</a></h1><div class="epigraph"><p>静态链接在构建时把库代码拷进镜像；动态链接只记下符号，把真正的地址留到加载或第一次调用再填。</p><footer>—— 据 Bryant and O&#39;Hallaron, Computer Systems: A Programmer&#39;s Perspective 第 7 章；ISO/IEC 9899 整理</footer></div><p>上一课<a href="/cs/build-system">构建系统</a>把链接画成图上的一步，产出一份可执行文件。本课不重讲 Make，也不从 ELF 节区名表另起。缺口是：第一课已经点名动态链接，<strong>为何可执行文件里可以没有 <code>printf</code> 的指令，运行时却能跳进去</strong>。共享库把「解析符号」从构建推迟到进程启动之后。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态链接把用到的目标拷进镜像，地址在构建时钉死，发布简单，镜像大，库的安全修复要重新链接各程序。动态链接让许多进程映射同一份库代码，可执行文件只保留对外部符号的重定位记录。缺口因此不是「DLL 好不好」，而是<strong>两阶段解析</strong>：构建时确认符号存在（或允许未定义到加载时），加载器把库映进地址空间后写回真实地址。调用约定仍然有效，只是第一次间接可能多跳一次。</p><p>缺库、库版本与构建时看到的符号集不一致，会在启动或首次调用时失败，而不是在构建图的链接节点失败。这是构建系统漏掉的一类边：运行时依赖。版本课里的「可回放」对动态库更脆，必须连同库版本一起记录。</p><h3 id="动态链接不是「运行时编译」" tabindex="-1">动态链接不是「运行时编译」 <a class="header-anchor" href="#动态链接不是「运行时编译」" aria-label="Permalink to &quot;动态链接不是「运行时编译」&quot;">​</a></h3><p>加载器做的是映射与重定位，不是把 C 再编译一遍。符号查找按约定的搜索路径与顺序，可能解析到你没打算用的那一份同名库。把动态链接理解成解释执行，会与后课系统调用、地址空间搞混。JIT 是另一回事，本栏不写。</p><p><span class="marginnote">CSAPP 第 7 章用过程链接表与全局偏移表说明：调用先跳到一段可写槽，第一次解析后改写成直接跳转。ISO C 仍把程序看成链接后的整体；动态库是实现把「整体」推迟拼完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>构建时对共享库做未完成的重定位：代码里对外部函数的调用走进过程链接表（PLT），数据引用走进全局偏移表（GOT）。加载时，动态链接器按依赖列表映射库，解析符号，填充 GOT。惰性绑定把函数符号的解析推迟到首次调用，以加快启动。<code>dlopen</code> 一类接口让解析发生在 <code>main</code> 之后，本课只点名。</p>',11)),(e(),n(c,null,{default:t(()=>[E(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXE%5B%22%E5%8F%AF%E6%89%A7%E8%A1%8C%E6%96%87%E4%BB%B6%EF%BC%9A%E8%AE%B0%E4%B8%8B%E6%9C%AA%E8%A7%A3%E6%9E%90%E7%AC%A6%E5%8F%B7%22%5D%20--%3E%20LOAD%5B%22%E5%8A%A0%E8%BD%BD%E5%99%A8%E6%98%A0%E5%B0%84%E5%85%B1%E4%BA%AB%E5%BA%93%22%5D%0A%20%20LOAD%20--%3E%20RES%5B%22%E8%A7%A3%E6%9E%90%E7%AC%A6%E5%8F%B7%E5%B9%B6%E5%A1%AB%E8%A1%A8%22%5D%0A%20%20RES%20--%3E%20CALL%5B%22%E8%B0%83%E7%94%A8%E8%BF%9B%E5%85%A5%E5%BA%93%E4%BB%A3%E7%A0%81%22%5D%0A%20%20STAT%5B%22%E9%9D%99%E6%80%81%E9%93%BE%E6%8E%A5%22%5D%20--%3E%20COPY%5B%22%E6%9E%84%E5%BB%BA%E6%97%B6%E6%8B%B7%E5%85%A5%E9%95%9C%E5%83%8F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>位置无关代码让同一库能映到不同进程的不同基址。这为后课地址空间随机化做准备，本课只需要：库内的地址也是相对的，加载后再定。</p><p>构建时用的共享库与运行时搜到的库可以不是同一文件：<code>rpath</code>、<code>LD_LIBRARY_PATH</code> 与系统默认路径组成搜索顺序。这是第一课「链接解析符号」在时间上的延长。静态链接没有这条搜索，镜像自足，但也失去了不重链就能打补丁的能力。两种模型可以在同一进程里混合：可执行文件静态链一部分，再动态依赖 libc。后课系统调用仍从 libc 包装进去，与这份库从哪来无关——陷入的是内核，不是 <code>.so</code> 文件本身。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>间接表让代码段可以只读共享：各进程私有的是 GOT 里的地址，不是整份指令。第一次调用的额外跳转是启动与热路径之间的折中。符号冲突（两份库提供同名强符号）按搜索顺序决胜，症状可以是「调用进了错误实现」，类型系统帮不上忙——又一次，链接器看名字不看 C 类型。</p><p>位置无关代码让库能被映到随机基址：指令用相对寻址，绝对地址只出现在可写的 GOT 里。这与后课地址空间一览直接衔接——同一库在两进程里的虚地址可以不同，物理页仍可共享只读代码。惰性绑定把首次调用变成「解析再跳转」，多线程下需要绑定过程自身的同步，那是实现细节。符号版本让同一名字在库演进后仍能绑到旧实现；没有版本时，升级库等于默默改所有已构建程序的契约。这比静态链接更需要把库版本写进部署记录。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不画完整 ELF 重定位类型，不讲符号版本脚本的全部语义。下一课<a href="/cs/syscall-as-boundary">系统调用作为边界</a>把控制从用户代码再送出一次，对象换成内核。后课默认：动态库在加载或首次调用时完成符号解析；可执行文件可以不含库的指令；运行时搜索路径是契约的一部分。</p><p>未定义符号若延迟到加载时才报，构建图的链接节点会绿、进程启动才红。把运行时依赖写进清单，与源一同版本管理，回放才包含库。静态链接没有这条时间差，代价是镜像更大、补丁要重链。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>动态链接推迟符号解析；静态链接在构建时拷贝代码。</li><li>PLT/GOT 用一次间接换来只读共享的代码段。</li><li>库版本与搜索路径是构建图之外的依赖。</li><li>下一课穿过用户与内核的边界。</li><li>出处：CSAPP 第 7 章；ISO C 的程序仍视为链接后的整体。</li></ul>',10))])}const f=i(p,[["render",A]]);export{P as __pageData,f as default};
